onClick:
{{
  (async function() {
    // 1. Récupération de l'ID client
    const data = Get_Location_Detail.data?.[0] || Get_Location_Detail.data?.[0];
    const clientId = data?.ID_Client;

    if (!clientId) {
      showAlert("Aucun ID client trouvé pour cette location", "warning");
      return;
    }

    // 2. Sauvegarde dans la mémoire Appsmith
    await storeValue('detail_client_id', clientId);
    await storeValue('page_precedente', 'Détail Location');
    await storeValue('id_precedent', appsmith.URL.queryParams.id);

    // 3. Navigation avec passage du paramètre ID dans l'URL !
    await navigateTo('Détail Client', { id: clientId });
  })()
}}
